    ```
    app.MapGet("/book/{id}", Results<Ok<Book>, NotFound> 
        (int id, List<Book> bookList) =>
        {
            return bookList.FirstOrDefault((i) => i.Id == id) is Book book
            ? TypedResults.Ok(book)
            : TypedResults.NotFound();
        });
    ```

